export const metroProj = (f: { latMin: number; latMax: number; lngMin: number; lngMax: number; W: number; H: number }, lat: number, lng: number) => ({
  x: ((lng - f.lngMin) / (f.lngMax - f.lngMin)) * f.W,
  y: ((f.latMax - lat) / (f.latMax - f.latMin)) * f.H,
});

